import{z as o,x as s,o as A,c as d,q as i,j as n,D as B,d as e,s as l,S as r,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"印度市场","description":"","frontmatter":{"title":"印度市场","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gm-india.md","filePath":"quant/gm-india.md","lastUpdated":1791063341000}'),p={name:"quant/gm-india.md"};function D(S,E,m,T,u,h){const t=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=i('<h1 id="印度市场" tabindex="-1">印度市场 <a class="header-anchor" href="#印度市场" aria-label="Permalink to &quot;印度市场&quot;">​</a></h1><div class="epigraph"><p>印度把两件相反的事放在一起：结算周期跑到全球最前，价格限制与交付纪律却是最老式的一档——资金效率与失败惩罚绑在同一笔交易上，制度在这里不是背景板而是现金流。</p><footer>—— 据 SEBI 与 NSE / BSE 公开规则（结算周期、T+0 可选框架、交付失败拍卖）整理</footer></div><p><a href="/quant/gm-hongkong">上一课</a>把港股的账算到税费与通道。印度把这个方向推到底：现金市场全面 T+1 结算、再向品种受限的 T+0 可选档推进，同时保留个股价格带、指数分档熔断与交付失败的强制拍卖。两件事相乘，策略的可行集由「合规纪律」逐日决定。本课写印度的结算、限制与卖空三件套。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>第一缺口是结算周期对资金与操作链的含义：T+1 把信用敞口窗口压到一天，全球最短的结算周期之一意味着保证金与资本效率上升，但对账、公司行动、跨境托管的处理窗口同步压缩——后链跟不上，前台的周期红利会被失败率吃掉。T+0 可选档进一步把「成交与结算同日」变成现实，但品种与时段受限，且预资金问题换了一种形态：资金不再提前划给券商，而是在投资者账户内被锁定（ASLP 一类的锁定机制），结算时才动用——理解错这个机制，资金占用与可用额度的计算就会错。第二缺口是限制族：个股按分档价格带限价、指数分档熔断，贴带的邻近效应与延迟发现照旧成立。第三缺口是卖空纪律：现金段日内可卖但须当日平结，隔夜卖空走借券（SLB），卖空未交付直接进拍卖补券——不是罚款了事。</p><p><span class="marginnote">「锁定而非划转」给个类比：划转像把钱先从钱包掏出来交给代购，锁定像把钱留在钱包里但贴了封条——钱还是你的、还在计息，只是动不了。ASLP 一类机制用的是后者：占用的额度，不是余额。把它当划转来算资金，会凭空少掉一笔可用头寸。</span></p><p><span class="marginnote">交付失败的拍卖纪律是印度制度里最硬的一条：回测里「允许卖空」不等于「卖空可执行」，可执行性要按借券可得性与失败拍卖的价格惩罚建模——按权利建模、按纪律受罚，是印度空腿的经典死法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>清单四项。场所与结构：NSE 与 BSE 并存、NSE 在指数衍生品上占绝对主导，衍生品与现金段的约束分开归档。结算与资金：按 T+1 为基线、T+0 档为特例建模；资金模型用「锁定非划转」口径，额度管理按锁定余额算。税费：STT 分边分品种（现金与衍生品、交收与日内各档），费后账单独列——它与港股印花税同为换手税，机制放到税课展开。限制与卖空：价格带带值按品种分档且可调整，「带收紧日」当事件处理；贴带邻近作为状态进入特征与风控，处理方式与<a href="/quant/cn-limit-proximity">涨跌停邻近效应</a>同族；空腿按 SLB 可得性与拍卖惩罚做可行性过滤。</p><p><span class="marginnote">「SLB」就是证券借贷的缩写：把愿意长期持有的券借给想做空的人，借入方付费用、交抵押，到期还券。它是隔夜空腿的唯一合法通道——没有 SLB 可借，隔夜卖空在印度现金市场不是「贵」，而是「不存在」。</span></p>',10)),(A(),n(r,null,{default:B(()=>[l(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22T%2B1%20%E5%85%A8%E9%9D%A2%E7%BB%93%E7%AE%97%22%5D%20--%3E%20T0%5B%22T%2B0%20%E5%8F%AF%E9%80%89%E6%A1%A3%EF%BC%9A%E5%93%81%E7%A7%8D%E4%B8%8E%E6%97%B6%E6%AE%B5%E5%8F%97%E9%99%90%22%5D%0A%20%20T0%20--%3E%20ASLP%5B%22ASLP%EF%BC%9A%E8%B4%A6%E6%88%B7%E5%86%85%E9%94%81%E5%AE%9A%E8%80%8C%E9%9D%9E%E9%A2%84%E5%85%88%E5%88%92%E8%BD%AC%22%5D%0A%20%20BAND%5B%22%E4%B8%AA%E8%82%A1%E5%88%86%E6%A1%A3%E4%BB%B7%E6%A0%BC%E5%B8%A6%22%5D%20--%3E%20PROX%5B%22%E8%B4%B4%E5%B8%A6%EF%BC%9A%E9%82%BB%E8%BF%91%E4%B8%8E%E5%BB%B6%E8%BF%9F%E5%8F%91%E7%8E%B0%22%5D%0A%20%20IDX%5B%22%E6%8C%87%E6%95%B0%E5%88%86%E6%A1%A3%E7%86%94%E6%96%AD%22%5D%20--%3E%20HALT%5B%22%E5%88%86%E6%AE%B5%E6%9A%82%E5%81%9C%E4%B8%8E%E9%87%8D%E5%BC%80%22%5D%0A%20%20SS%5B%22%E6%97%A5%E5%86%85%E5%8D%96%E7%A9%BA%E9%A1%BB%E5%BD%93%E6%97%A5%E4%BA%86%E7%BB%93%22%5D%20--%3E%20SLB%5B%22%E9%9A%94%E5%A4%9C%E7%A9%BA%E8%85%BF%E8%B5%B0%20SLB%20%E5%80%9F%E5%88%B8%22%5D%0A%20%20SS%20--%3E%20AUC%5B%22%E4%BA%A4%E4%BB%98%E5%A4%B1%E8%B4%A5%E8%BF%9B%E5%BC%BA%E5%88%B6%E6%8B%8D%E5%8D%96%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"结算周期与交付纪律是一对齿轮。周期缩短的机制收益是信用与占用下降；机制代价是所有后链动作跟着压缩，于是印度策略的真实约束从「资金成本」迁移到「操作纪律」。拍卖机制把失败成本变成价格发现的一部分：拍卖价相对市价的惩罚是空腿成本函数的一项，忽略它的高估收益在压力日集中兑现。价格带与熔断的机制与前面各课同构：贴带截断发现、熔断把流量切到重开——不同点在带值分档且会被调整，制度参数本身有事件性。ASLP 的机制意义是把预资金从「转移」改成「锁定」：占用的是额度而不是余额，日内资金周转的计算口径随之改变。",-1)),E[5]||(E[5]=a("p",null,"一笔卖空从「借不到券」到「被拍卖惩罚」要经过哪几步、成本在哪里放大，这条链条回答的是「空腿的真实成本怎么算」：",-1)),(A(),n(r,null,{default:B(()=>[l(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%8D%96%E7%A9%BA%E6%88%90%E4%BA%A4%20T%20%E6%97%A5%22%5D%20--%3E%20Q%7B%22%E7%BB%93%E7%AE%97%E6%97%A5%E6%9C%89%E5%88%B8%E5%8F%AF%E4%BA%A4%3F%22%7D%0A%20%20Q%20--%20%22%E5%B7%B2%E5%80%9F%E5%88%B0%20SLB%20%E5%88%B8%22%20--%3E%20D%5B%22%E6%AD%A3%E5%B8%B8%E4%BA%A4%E4%BB%98%22%5D%0A%20%20Q%20--%20%22%E5%80%9F%E4%B8%8D%E5%88%B0%E6%88%96%E5%BF%98%E5%80%9F%22%20--%3E%20Fail%5B%22%E4%BA%A4%E4%BB%98%E5%A4%B1%E8%B4%A5%20%E8%BF%9B%E5%BC%BA%E5%88%B6%E6%8B%8D%E5%8D%96%22%5D%0A%20%20Fail%20--%3E%20Auc%5B%22%E4%BA%A4%E6%98%93%E6%89%80%E4%BB%A5%E6%8B%8D%E5%8D%96%E8%A1%A5%E5%88%B8%22%5D%0A%20%20Auc%20--%3E%20P%5B%22%E6%88%90%E4%BA%A4%E4%BB%B7%E5%B8%B8%E5%8A%A3%E4%BA%8E%E5%B8%82%E4%BB%B7%20%E6%83%A9%E7%BD%9A%E6%80%A7%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20P%20--%3E%20C%5B%22%E6%83%A9%E7%BD%9A%E8%AE%A1%E5%85%A5%E7%A9%BA%E8%85%BF%E6%88%90%E6%9C%AC%20%E8%BF%98%E5%8F%AF%E8%83%BD%E9%99%90%E6%9D%83%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=i('<p><span class="marginnote">数字实例：假设卖空价 100 元，结算日借不到券、进拍卖，拍得价 103 元。惩罚是每股 3 元，即空腿收益直接缩水 3%；若同一周恰逢交付失败高发，多笔空腿叠加，整段策略的账面利润可以被拍卖惩罚吃光——这就是「按权利建模、按纪律受罚」的算术含义。</span></p><p>不这么做会错在哪：把 T+0 档当普通加速器、按「划转」算资金，会在额度上高估可交易规模；把卖空当权利、忽略拍卖惩罚，回测收益会在交付失败集中发生的时段归零。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写印度散户衍生品热度的行为解释，不写 FPI 框架下的资本进出细节——跨境通道的摩擦统一放到跨市场套利课。带值、档位、STT 税率与 T+0 档范围都在滚动调整，清单按 SEBI 与交易所当期文本重读。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>印度的对象是「最短结算周期加速度交付纪律」：T+1 全面化、T+0 档受限推进。</li><li>资金占用按「账户内锁定」口径（ASLP 一类）计算，不是预先划转。</li><li>价格带分档可调，贴带与熔断按事件与状态处理，邻近效应同族适用。</li><li>空腿可行性由 SLB 可得性与交付失败拍卖惩罚决定，不是由「允许卖空」决定。</li><li>出处：SEBI 与 NSE / BSE 公开规则（结算周期、T+0 框架、交付失败拍卖）；价格限制实证传统见 Kim and Rhee, 1997。</li></ul>',6))])}const _=o(p,[["render",D]]);export{f as __pageData,_ as default};
